window.docContents[133].resolve({"/rules/PL1002/#PL1002-rationale":{"contents":"sorryAx proves every proposition. A declaration that depends on it has no evidence, even if Lean elaborated the file, and every theorem that uses it inherits the gap.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1002: Proof holes are forbidden","header":"Why it matters","id":"/rules/PL1002/#PL1002-rationale"},"/rules/PL2001/#PL2001-rationale":{"contents":"Every conformance claim is about one exact elaboration environment: toolchain, dependency revisions and source state. A result under an unknown or different environment is not evidence for the declared one.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2001: The declared Lean environment must be available","header":"Why it matters","id":"/rules/PL2001/#PL2001-rationale"}});